import{_ as n,o as r,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"24. März 2026: Die Rochade der Macht – OÖ geht auf Distanz","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/2026-03-24-die-rochade-der-macht.md","filePath":"logbuch/2026-03-24-die-rochade-der-macht.md"}'),t={name:"logbuch/2026-03-24-die-rochade-der-macht.md"};function s(d,e,h,o,c,l){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_24-marz-2026-die-rochade-der-macht-–-oo-geht-auf-distanz" tabindex="-1">24. März 2026: Die Rochade der Macht – OÖ geht auf Distanz <a class="header-anchor" href="#_24-marz-2026-die-rochade-der-macht-–-oo-geht-auf-distanz" aria-label="Permalink to &quot;24. März 2026: Die Rochade der Macht – OÖ geht auf Distanz&quot;">​</a></h1><p>Heute am Dienstag verdichten sich die Hinweise darauf, dass die oberösterreichische Volkspartei (OÖVP) die Ära Wöginger auf Landesebene geordnet beenden möchte. Während August Wöginger am Landesgericht Linz weiterhin gegen die Vorwürfe der Anstiftung zum Amtsmissbrauch kämpft, ist die strategische Entscheidung gefallen: <strong>Wolfgang Hattmannsdorfer</strong> übernimmt seine Rolle in der Landesspitze.</p><h2 id="forensische-analyse-der-lage" tabindex="-1">Forensische Analyse der Lage: <a class="header-anchor" href="#forensische-analyse-der-lage" aria-label="Permalink to &quot;Forensische Analyse der Lage:&quot;">​</a></h2><ol><li><strong>Die Stelzer-Distanz:</strong> Landeshauptmann Thomas Stelzer vollzieht eine klassische politische Rochade. Durch die Nominierung Hattmannsdorfers zum Stellvertreter schafft er eine personelle Brandmauer zwischen der Landespartei und dem laufenden Prozess gegen Wöginger. Man möchte am Landesparteitag (24. April) „sauber“ dastehen – nur drei Tage nach dem erwarteten Urteil.</li><li><strong>Wögingers Bundes-Festung:</strong> Interessanterweise zeigt Wöginger auf Bundesebene keinerlei Rückzugstendenzen. Er behält seine Rolle als Klubobmann im Nationalrat eisern bei. Die Strategie scheint klar: Das Land opfern, um den Bund (und die dortige „Harte Prosa“) zu halten.</li><li><strong>Hattmannsdorfer als Profiteur:</strong> Der Wirtschaftsminister festigt seinen Ruf als „Kronprinz“. Er rückt in das Stellvertreter-Team auf und wird zum wichtigsten Bindeglied zwischen Wien und Linz. In unserem Archiv führen wir ihn nun als „Starken Mann der Zukunft“.</li></ol><h2 id="die-stimmung-im-archiv" tabindex="-1">Die Stimmung im Archiv: <a class="header-anchor" href="#die-stimmung-im-archiv" aria-label="Permalink to &quot;Die Stimmung im Archiv:&quot;">​</a></h2><p>Unsere Zugriffszahlen zeigen, dass die Öffentlichkeit die Trennung zwischen Landes- und Bundesfunktion als taktisches Manöver durchschaut. Der Viralitäts-Index stabilisiert sich auf hohem Niveau, während die Forensik-Einheit neue Querverbindungen zwischen Hattmannsdorfers Aufstieg und den WKO-Netzwerken prüft.</p><hr><p><em>Morgen: Ein tieferer Blick in die WKO-Netzwerke des neuen Kronprinzen.</em></p>',8)])])}const m=n(t,[["render",s]]);export{g as __pageData,m as default};
